BEGIN TRANSACTION;
CREATE TABLE accounts (
	account_id VARCHAR NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	account_status VARCHAR(30) NOT NULL, 
	opened_at DATE NOT NULL, 
	closed_at DATE, 
	PRIMARY KEY (account_id), 
	CHECK (account_status IN ('active', 'closed')), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE audit_events (
	event_id VARCHAR NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(100) NOT NULL, 
	event_type VARCHAR(50) NOT NULL, 
	event_timestamp DATETIME, 
	old_value TEXT, 
	new_value TEXT, 
	actor_type VARCHAR(30) NOT NULL, 
	notes TEXT, 
	PRIMARY KEY (event_id)
);
CREATE TABLE collection_cases (
	case_id VARCHAR NOT NULL, 
	loan_id VARCHAR NOT NULL, 
	snapshot_id VARCHAR, 
	priority_score FLOAT NOT NULL, 
	priority_band VARCHAR(20) NOT NULL, 
	case_status VARCHAR(30) NOT NULL, 
	opened_at DATETIME, 
	closed_at DATETIME, 
	issue_type VARCHAR(100), 
	PRIMARY KEY (case_id), 
	CHECK (priority_score >= 0 AND priority_score <= 100), 
	CHECK (priority_band IN ('low', 'medium', 'high')), 
	CHECK (case_status IN ('open', 'on_hold', 'closed', 'review')), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id), 
	FOREIGN KEY(snapshot_id) REFERENCES delinquency_snapshots (snapshot_id)
);
CREATE TABLE contact_attempts (
	attempt_id VARCHAR NOT NULL, 
	case_id VARCHAR NOT NULL, 
	preference_id VARCHAR, 
	channel VARCHAR(30) NOT NULL, 
	attempted_at DATETIME NOT NULL, 
	outcome VARCHAR(30) NOT NULL, 
	blocked BOOLEAN, 
	block_reason TEXT, 
	PRIMARY KEY (attempt_id), 
	CHECK (outcome IN ('connected', 'no_answer', 'promise', 'dispute', 'refused', 'blocked')), 
	FOREIGN KEY(case_id) REFERENCES collection_cases (case_id), 
	FOREIGN KEY(preference_id) REFERENCES contact_preferences (preference_id)
);
CREATE TABLE contact_preferences (
	preference_id VARCHAR NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	channel VARCHAR(30) NOT NULL, 
	permitted_start TIME NOT NULL, 
	permitted_end TIME NOT NULL, 
	timezone VARCHAR(50), 
	do_not_contact BOOLEAN, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	PRIMARY KEY (preference_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE customers (
	customer_id VARCHAR NOT NULL, 
	first_name VARCHAR(100) NOT NULL, 
	last_name VARCHAR(100) NOT NULL, 
	email VARCHAR(255), 
	phone VARCHAR(20), 
	created_at DATETIME, 
	PRIMARY KEY (customer_id), 
	UNIQUE (email)
);
CREATE TABLE delinquency_snapshots (
	snapshot_id VARCHAR NOT NULL, 
	loan_id VARCHAR NOT NULL, 
	snapshot_date DATE NOT NULL, 
	days_past_due INTEGER NOT NULL, 
	total_arrears NUMERIC(14, 2) NOT NULL, 
	outstanding_balance NUMERIC(14, 2) NOT NULL, 
	risk_category VARCHAR(30) NOT NULL, 
	disputed BOOLEAN, 
	hardship_flag BOOLEAN, 
	PRIMARY KEY (snapshot_id), 
	UNIQUE (loan_id, snapshot_date), 
	CHECK (days_past_due >= 0), 
	CHECK (total_arrears >= 0), 
	CHECK (outstanding_balance >= 0), 
	CHECK (risk_category IN ('low', 'medium', 'high')), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id)
);
CREATE TABLE installments (
	installment_id VARCHAR NOT NULL, 
	loan_id VARCHAR NOT NULL, 
	installment_number INTEGER NOT NULL, 
	due_date DATE NOT NULL, 
	amount_due NUMERIC(14, 2) NOT NULL, 
	amount_paid NUMERIC(14, 2) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (installment_id), 
	UNIQUE (loan_id, installment_number), 
	CHECK (installment_number > 0), 
	CHECK (amount_due > 0), 
	CHECK (amount_paid >= 0), 
	CHECK (status IN ('scheduled', 'partially_paid', 'paid', 'overdue')), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id)
);
CREATE TABLE loans (
	loan_id VARCHAR NOT NULL, 
	account_id VARCHAR NOT NULL, 
	principal_amount NUMERIC(14, 2) NOT NULL, 
	annual_interest_rate NUMERIC(6, 3) NOT NULL, 
	term_months INTEGER NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	loan_status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (loan_id), 
	CHECK (principal_amount > 0), 
	CHECK (annual_interest_rate >= 0), 
	CHECK (term_months > 0), 
	CHECK (loan_status IN ('active', 'paid_off', 'defaulted')), 
	FOREIGN KEY(account_id) REFERENCES accounts (account_id)
);
CREATE TABLE payment_allocations (
	allocation_id VARCHAR NOT NULL, 
	payment_id VARCHAR NOT NULL, 
	installment_id VARCHAR NOT NULL, 
	allocated_amount NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (allocation_id), 
	CHECK (allocated_amount > 0), 
	FOREIGN KEY(payment_id) REFERENCES payments (payment_id), 
	FOREIGN KEY(installment_id) REFERENCES installments (installment_id)
);
CREATE TABLE payments (
	payment_id VARCHAR NOT NULL, 
	loan_id VARCHAR NOT NULL, 
	payment_date DATE NOT NULL, 
	amount NUMERIC(14, 2) NOT NULL, 
	payment_method VARCHAR(30) NOT NULL, 
	payment_status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (payment_id), 
	CHECK (amount > 0), 
	CHECK (payment_status IN ('received', 'reversed', 'failed')), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id)
);
CREATE TABLE promise_payment_allocations (
	id INTEGER NOT NULL, 
	promise_id VARCHAR NOT NULL, 
	payment_id VARCHAR NOT NULL, 
	allocated_amount NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (promise_id, payment_id), 
	CHECK (allocated_amount > 0), 
	FOREIGN KEY(promise_id) REFERENCES promises_to_pay (promise_id), 
	FOREIGN KEY(payment_id) REFERENCES payments (payment_id)
);
CREATE TABLE promises_to_pay (
	promise_id VARCHAR NOT NULL, 
	case_id VARCHAR NOT NULL, 
	attempt_id VARCHAR, 
	promised_amount NUMERIC(14, 2) NOT NULL, 
	promised_date DATE NOT NULL, 
	promise_status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (promise_id), 
	CHECK (promised_amount > 0), 
	CHECK (promise_status IN ('pending', 'fulfilled', 'missed', 'cancelled', 'invalid')), 
	FOREIGN KEY(case_id) REFERENCES collection_cases (case_id), 
	FOREIGN KEY(attempt_id) REFERENCES contact_attempts (attempt_id)
);
COMMIT;
